export const removeRiver=(s,key,confirmed=false,o={})=>str(key,1000)&&confirmed===true&&change(s,c=>{if(!own(c.riverRoom?.visits,key))return false;delete c.riverRoom.visits[key];if(c.riverRoom.current===key)c.riverRoom.current='';return true;},o);
export function riverFacts(s){try{
 const w=riverView(s).work;if(!w)return [];const source=w.source,found=new Map();
 const add=(a,b)=>{if(int(a,1,12)&&int(b,1,12))for(const p of [[a,b],[b,a]])found.set(p.join('x'),p);};
 const addDefinition=(definitions,code)=>{if(own(definitions,code))for(const pair of definitions[code].facts)add(...pair);};
 const addRequested=code=>{if(w.help.includes(code))addDefinition(source.help,code);};
 // Model summaries and response context print side lengths and area, not the
 // archived tile or the bodies of help recorded before that model was kept.
 const addModel=m=>{if(validRiverModel(m)&&m.otherSide.d===1)add(m.width,m.otherSide.n);};
 const addCheck=c=>{if(!validRiverCheck(c))return;if(c.modelContext)addModel(c.modelContext);const t=taskOf(c.source,c.taskId);for(const pair of t?.facts||[])add(...pair);};
 addDefinition(source.display,`page-${w.page}`);
 if(w.page===0)addDefinition(source.display,w.amounts.history);
 if(w.page===3)addDefinition(source.display,w.amounts.lent);
 const currentTasks=source.tasks.filter(t=>t.page===w.page);
 for(const t of currentTasks){addRequested(t.hintId);addRequested(t.exampleId);}
 // Opened reference definitions are rendered on every case page. Discussion
 // source cards and the adult design card are also locally available in DOM.
 for(const card of source.sources){if(card.id==='design')addDefinition(source.help,`source-${card.id}`);else addRequested(`source-${card.id}`);}
 for(const word of source.glossary)addRequested(`glossary-${word.id}`);
 for(const discussion of source.discussions.filter(d=>d.page===w.page)){
  for(const sourceId of discussion.sourceIds)addDefinition(source.help,`source-${sourceId}`);
  for(const option of discussion.options)addRequested(`discussion-${discussion.id}-${option.id}`);
 }
 if(w.page===1)for(const measureId of source.analogy.measures)for(const plan of source.analogy.plans)addRequested(`analogy-${measureId}-${plan.id}`);
 if(w.page===2){
  add(source.geometry.tile.rows,source.geometry.tile.columns);
  const rectangle=riverRectangle(source.geometry,w.modelWidth);if(rectangle?.otherSide.d===1)add(w.modelWidth,rectangle.otherSide.n);
  for(const model of w.models.filter(validRiverModel).slice(-2))addModel(model);
 }
 // Match the UI's history selector: a malformed latest response remains an
 // unreadable latest response, and an unseen middle response is not substituted.
 const taskIds=[...currentTasks.map(t=>t.id),...(w.page===0?[source.historyTask.id]:[]),...(w.page===1?[source.sortTask.id]:[])];
 for(const taskId of taskIds){
  const latest=w.checks.filter(c=>obj(c)&&own(c,'taskId')&&c.taskId===taskId).at(-1);
  if(latest)addCheck(latest);
  if(own(w.firstChecks,taskId))addCheck(w.firstChecks[taskId]);
 }
 if(w.page===4)for(const kept of [w.firstKept,w.kept])if(validRiverKeep(kept))for(const model of kept.models)addModel(model);
 return [...found.values()];
 }catch{return [];}}
export function prepareRiverDisplay(s,o={}){try{if(!riverView(s).work)return {ok:true,changed:false};const c=clone(s);o.exposeFacts?.(riverFacts(c),c);const changed=JSON.stringify(c)!==JSON.stringify(s);if(!fits(c,o))return {ok:false,changed:false};if(!changed)return {ok:true,changed:false};commit(s,c);return {ok:true,changed:true};}catch{return {ok:false,changed:false};}}
